import { build } from "esbuild";
import { execSync } from "node:child_process";
import path from "node:path";
const root = process.cwd();
const measure = async (label, overrides) => {
  const code = `import { H3Core } from "./src/index.ts"; const app = new H3Core();`;
  const r = await build({
    stdin: { contents: code, resolveDir: root, loader: "ts" },
    bundle: true, minify: true, format: "esm", write: false, platform: "neutral", treeShaking: true,
    plugins: [{ name: "ov", setup(b) {
      b.onLoad({ filter: /src[\\/](error|response)\.ts$/ }, (args) => {
        const rel = path.relative(root, args.path).split(path.sep).join("/");
        const contents = overrides && overrides[rel]
          ? execSync(`git show ${overrides[rel]}:${rel}`, { encoding: "utf8" })
          : undefined;
        return contents === undefined ? undefined : { contents, loader: "ts", resolveDir: path.dirname(args.path) };
      });
    }}],
  });
  console.log(label, r.outputFiles[0].contents.length);
};
await measure("current", null);
await measure("baseline", { "src/error.ts": "HEAD", "src/response.ts": "HEAD" });
EOF
node .measure-tmp.mjs; rm -f .measure-tmp.mjs

