    expect(await t.fetch("/api/caf%C3%A9?q=1").then((r) => r.text())).toBe("/caf%C3%A9?q=1");
    // ...and the raw url is restored once the handler settles
    expect(rawUrlAfter).toBe("/api/caf%C3%A9?q=1");
