      it("allows modifying response event async", async () => {
        t.app.all("/", (event) => {
          return proxyRequest(event, "/debug", {
            onResponse(_event) {
              return new Promise((resolve) => {
                resolve(event.res.headers.set("x-custom", "hello"));
